schema:
CREATE TABLE Business_Attributes (
  attribute_id,
  attribute_value,
  business_id
);

CREATE TABLE Business_Hours (
  business_id,
  closing_time,
  day_id,
  opening_time
);

CREATE TABLE Tips (
  business_id,
  likes,
  tip_length,
  user_id
);

CREATE TABLE Users_Compliments (
  compliment_id,
  number_of_compliments,
  user_id
);
